package io.forgeloop.control.domain;
import jakarta.persistence.*;import java.util.*;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"organization_id","name"})) public class LocalMcpConfiguration{
 @Id @GeneratedValue(strategy=GenerationType.UUID)private String id;@Column(nullable=false)private String organizationId;@Column(nullable=false,length=80)private String name;@Column(nullable=false,length=500)private String command;@Column(nullable=false,length=4000)private String arguments;@Column(nullable=false,length=1000)private String allowedRoles;@Column(nullable=false,length=120)private String contextTool;@Column(nullable=false,length=4000)private String toolArguments;private boolean enabled;private int revision;
 protected LocalMcpConfiguration(){}public LocalMcpConfiguration(String org,String name,String command,List<String> arguments,List<String> roles,String tool,String toolArguments){if(org==null||org.isBlank()||name==null||!name.matches("[A-Za-z][A-Za-z0-9_-]{1,79}")||command==null||command.isBlank()||command.length()>500||arguments==null||roles==null||roles.isEmpty()||tool==null||!tool.matches("[A-Za-z0-9_.-]{1,120}")||toolArguments==null||toolArguments.length()>4000)throw new IllegalArgumentException("Local MCP configuration is invalid");if(arguments.stream().anyMatch(a->a.contains("\n")||a.length()>500))throw new IllegalArgumentException("MCP argument is invalid");organizationId=org;this.name=name;this.command=command;this.arguments=String.join("\n",arguments);allowedRoles=String.join(",",new LinkedHashSet<>(roles));contextTool=tool;this.toolArguments=toolArguments;enabled=true;revision=1;}
 public boolean belongsTo(String org){return organizationId.equals(org);}public boolean allows(String role){return getAllowedRoles().contains(role);}public String getId(){return id;}public String getName(){return name;}public String getCommand(){return command;}public List<String> getArguments(){return arguments.isBlank()?List.of():arguments.lines().toList();}public List<String> getAllowedRoles(){return Arrays.stream(allowedRoles.split(",")).toList();}public String getContextTool(){return contextTool;}public String getToolArguments(){return toolArguments;}public boolean isEnabled(){return enabled;}public int getRevision(){return revision;}
}
